        mockMvc.perform(get("/api/observations/resolutions/{resolutionId}", "res-missing"))
                .andExpect(status().isNotFound());
        mockMvc.perform(get("/api/observations/{id}/resolutions", "obs-missing"))
                .andExpect(status().isNotFound());
    }
