        List<CorrigendumService.CorrigendumOutcome> outcomes = runConcurrently(tasks);

        assertThat(outcomes).allMatch(o -> o.body().appendixId().equals("ap-c2"));
        assertThat(outcomes).allMatch(o -> o.body().appendixVersion() == 1);
